            onPress={handleOpenFilters}
          >
            <Text style={styles.filterButtonText}>Filters</Text>
            {activeFilterCount > 0 && (
              <View style={styles.filterBadge} testID="filter-badge">
                <Text style={styles.filterBadgeText}>{activeFilterCount}</Text>
              </View>
            )}
          </Pressable>

          {/* Placeholder for SortDropdown */}
          <Pressable
            testID="discover-sort-button"
            accessibilityLabel={`Sort by ${sortBy}`}
            style={styles.sortButton}
            onPress={() => {
              // TODO: Implement sort dropdown
              console.log('Sort button tapped');
            }}
          >
            <Text style={styles.sortButtonText}>Sort: {sortBy}</Text>
          </Pressable>
        </View>

        {/* Network Error Banner */}
        {error && (
          <Pressable
            testID="network-error-banner"
            style={styles.errorBanner}
            onPress={handleRetry}
          >
            <Text style={styles.errorBannerText}>⚠️ {error}. Tap to retry.</Text>
          </Pressable>
        )}

        {/* Autocomplete Panel */}
        {autocompleteVisible && searchFocused && autocompleteSuggestions.length > 0 && (
          <View style={styles.autocompletePanel} testID="autocomplete-panel">
            {autocompleteSuggestions.map((suggestion, index) => (
              <Pressable
                key={`autocomplete-${index}`}
                testID={`autocomplete-suggestion-${index}`}
